1	package main
2	
3	import (
4		"encoding/json"
5		"errors"
6		"net/http"
7		"strings"
8		"time"
9	)
10	
11	const maxTags = 5
12	
13	type Server struct {
14		store *Store
15		loc   *time.Location
16		// now is the clock; tests replace it.
17		now func() time.Time
18	}
19	
20	func NewServer(store *Store, loc *time.Location) *Server {
21		return &Server{store: store, loc: loc, now: time.Now}
22	}
23	
24	func (s *Server) Routes() http.Handler {
25		mux := http.NewServeMux()
26		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("ok\n")) })
27		mux.HandleFunc("GET /tasks", s.listTasks)
28		mux.HandleFunc("POST /tasks", s.createTask)
29		mux.HandleFunc("GET /tasks/{id}", s.getTask)
30		mux.HandleFunc("PATCH /tasks/{id}", s.patchTask)
31		mux.HandleFunc("DELETE /tasks/{id}", s.deleteTask)
32		return mux
33	}
34	
35	func writeJSON(w http.ResponseWriter, status int, v any) {
36		w.Header().Set("Content-Type", "application/json")
37		w.WriteHeader(status)
38		json.NewEncoder(w).Encode(v)
39	}
40	
41	func writeError(w http.ResponseWriter, status int, msg string) {
42		writeJSON(w, status, map[string]string{"error": msg})
43	}
44	
45	func normalizeTags(tags []string) ([]string, error) {
46		if len(tags) > maxTags {
47			return nil, errors.New("at most 5 tags")
48		}
49		out := make([]string, 0, len(tags))
50		for _, t := range tags {
51			t = strings.ToLower(strings.TrimSpace(t))
52			if t == "" {
53				return nil, errors.New("empty tag")
54			}
55			out = append(out, t)
56		}
57		return out, nil
58	}
59	
60	// today is the current calendar day in the service's configured time zone.
61	func (s *Server) today() Date {
62		n := s.now().In(s.loc)
63		return Date{time.Date(n.Year(), n.Month(), n.Day(), 0, 0, 0, 0, time.UTC)}
64	}
65	
66	func hasTag(t Task, tag string) bool {
67		for _, x := range t.Tags {
68			if x == tag {
69				return true
70			}
71		}
72		return false
73	}
74	
75	func (s *Server) listTasks(w http.ResponseWriter, r *http.Request) {
76		tag := strings.ToLower(r.URL.Query().Get("tag"))
77		overdue := r.URL.Query().Get("overdue") == "true"
78		today := s.today()
79		out := []Task{}
80		for _, t := range s.store.List() {
81			if tag != "" && !hasTag(t, tag) {
82				continue
83			}
84			if overdue && (t.Done || t.Due.After(today.Time)) {
85				continue
86			}
87			out = append(out, t)
88		}
89		writeJSON(w, http.StatusOK, out)
90	}
91	
92	type createReq struct {
93		Title string   `json:"title"`
94		Due   string   `json:"due"`
95		Tags  []string `json:"tags"`
96	}
97	
98	func (s *Server) createTask(w http.ResponseWriter, r *http.Request) {
99		var req createReq
100		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
101			writeError(w, http.StatusBadRequest, "invalid JSON body")
102			return
103		}
104		if strings.TrimSpace(req.Title) == "" {
105			writeError(w, http.StatusBadRequest, "title is required")
106			return
107		}
108		due, err := ParseDate(req.Due)
109		if err != nil {
110			writeError(w, http.StatusBadRequest, "due must be YYYY-MM-DD")
111			return
112		}
113		tags, err := normalizeTags(req.Tags)
114		if err != nil {
115			writeError(w, http.StatusBadRequest, err.Error())
116			return
117		}
118		t, err := s.store.Create(Task{Title: strings.TrimSpace(req.Title), Due: due, Tags: tags}, s.now())
119		if err != nil {
120			writeError(w, http.StatusInternalServerError, "could not save")
121			return
122		}
123		w.Header().Set("Location", "/tasks/"+t.ID)
124		writeJSON(w, http.StatusCreated, t)
125	}
126	
127	func (s *Server) getTask(w http.ResponseWriter, r *http.Request) {
128		t, err := s.store.Get(r.PathValue("id"))
129		if errors.Is(err, ErrNotFound) {
130			writeError(w, http.StatusNotFound, "task not found")
131			return
132		}
133		writeJSON(w, http.StatusOK, t)
134	}
135	
136	type patchReq struct {
137		Title string   `json:"title"`
138		Due   string   `json:"due"`
139		Tags  []string `json:"tags"`
140		Done  *bool    `json:"done"`
141	}
142	
143	func (s *Server) patchTask(w http.ResponseWriter, r *http.Request) {
144		var req patchReq
145		json.NewDecoder(r.Body).Decode(&req)
146		due, err := ParseDate(req.Due)
147		if err != nil {
148			writeError(w, http.StatusBadRequest, "due must be YYYY-MM-DD")
149			return
150		}
151		t, err := s.store.Update(r.PathValue("id"), func(t *Task) {
152			if req.Title != "" {
153				t.Title = strings.TrimSpace(req.Title)
154			}
155			t.Due = due
156			t.Tags = req.Tags
157			if req.Done != nil {
158				t.Done = *req.Done
159			}
160		})
161		if errors.Is(err, ErrNotFound) {
162			writeError(w, http.StatusNotFound, "task not found")
163			return
164		}
165		if err != nil {
166			writeError(w, http.StatusInternalServerError, "could not save")
167			return
168		}
169		writeJSON(w, http.StatusOK, t)
170	}
171	
172	func (s *Server) deleteTask(w http.ResponseWriter, r *http.Request) {
173		if err := s.store.Delete(r.PathValue("id")); err != nil {
174			writeError(w, http.StatusInternalServerError, "could not save")
175			return
176		}
177		w.WriteHeader(http.StatusNoContent)
178	}
