2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"strings"
8		"time"
9	)
10	
11	// taskV1 is the pre-TICKET-142 format: a bare JSON array, labels as one comma-separated
12	// string, and "created" instead of "created_at".
13	type taskV1 struct {
14		ID      string    `json:"id"`
15		Title   string    `json:"title"`
16		Done    bool      `json:"done"`
17		Labels  string    `json:"labels"`
18		Created time.Time `json:"created"`
19	}
20	
21	// Migrate upgrades a v1 tasks file to v2 in place. It keeps the original next to it as
22	// <path>.v1.bak so an operator can roll back by hand. A v2 file is left untouched, so
23	// running it on every start is safe.
24	func Migrate(path string) (bool, error) {
25		b, err := os.ReadFile(path)
26		if os.IsNotExist(err) {
27			return false, nil
28		}
29		if err != nil {
30			return false, err
31		}
32		trimmed := strings.TrimSpace(string(b))
33		if !strings.HasPrefix(trimmed, "[") {
34			return false, nil // already v2 (an object with "version")
35		}
36		var old []taskV1
37		if err := json.Unmarshal(b, &old); err != nil {
38			return false, fmt.Errorf("migrate %s: %w", path, err)
39		}
40		f := fileV2{Version: 2, NextID: 1}
41		for _, o := range old {
42			t := &Task{ID: o.ID, Title: o.Title, Done: o.Done}
43			if o.Labels != "" {
44				t.Tags = strings.Split(o.Labels, ",")
45			}
46			f.Tasks = append(f.Tasks, t)
47			var n int
48			if _, err := fmt.Sscanf(o.ID, "t%d", &n); err == nil && n >= f.NextID {
49				f.NextID = n + 1
50			}
51		}
52		if err := os.WriteFile(path+".v1.bak", b, 0o644); err != nil {
53			return false, err
54		}
55		out, err := json.MarshalIndent(f, "", "  ")
56		if err != nil {
57			return false, err
58		}
59		return true, os.WriteFile(path, out, 0o644)
60	}
