3	import (
4		"log"
5		"net/http"
6		"os"
7		"time"
8	)
9	
10	func env(k, def string) string {
11		if v := os.Getenv(k); v != "" {
12			return v
13		}
14		return def
15	}
16	
17	func main() {
18		addr := env("ADDR", "127.0.0.1:8080")
19		data := env("DATA", "data/tasks.json")
20		loc, err := time.LoadLocation(env("TZ_NAME", "Asia/Taipei"))
21		if err != nil {
22			log.Fatal(err)
23		}
24		migrated, err := Migrate(data)
25		if err != nil {
26			log.Fatal(err)
27		}
28		if migrated {
29			log.Printf("migrated %s to v2 (backup at %s.v1.bak)", data, data)
30		}
31		store, err := OpenStore(data)
32		if err != nil {
33			log.Fatal(err)
34		}
35		log.Printf("listening on http://%s", addr)
36		log.Fatal(http.ListenAndServe(addr, NewServer(store, loc).Routes()))
37	}
