11	)
12	
13	func newTestServer(t *testing.T) (*Server, http.Handler) {
14		t.Helper()
15		store, err := OpenStore(filepath.Join(t.TempDir(), "tasks.json"))
16		if err != nil {
17			t.Fatal(err)
18		}
19		loc, _ := time.LoadLocation("Asia/Taipei")
20		s := NewServer(store, loc)
21		s.now = func() time.Time { return time.Date(2026, 3, 10, 9, 0, 0, 0, loc) }
22		return s, s.Routes()
23	}
24	
25	func do(t *testing.T, h http.Handler, method, path, body string) *httptest.ResponseRecorder {
26		t.Helper()
27		req := httptest.NewRequest(method, path, strings.NewReader(body))
28		rec := httptest.NewRecorder()
29		h.ServeHTTP(rec, req)
30		return rec
31	}
32	
33	func decode[T any](t *testing.T, rec *httptest.ResponseRecorder) T {
34		t.Helper()
35		var v T
36		if err := json.Unmarshal(rec.Body.Bytes(), &v); err != nil {
37			t.Fatalf("decode %q: %v", rec.Body.String(), err)
38		}
39		return v
40	}
41	
42	func TestHealthz(t *testing.T) {
43		_, h := newTestServer(t)
44		if rec := do(t, h, "GET", "/healthz", ""); rec.Code != 200 {
45			t.Fatalf("got %d", rec.Code)
46		}
47	}
48	
49	func TestCreateAndGet(t *testing.T) {
50		_, h := newTestServer(t)
51		rec := do(t, h, "POST", "/tasks", `{"title":"Buy milk","due":"2026-03-12","tags":["Home"," errands "]}`)
52		if rec.Code != http.StatusCreated {
53			t.Fatalf("create: %d %s", rec.Code, rec.Body)
54		}
55		created := decode[Task](t, rec)
56		if created.ID != "t0001" || created.Due.Format(dateLayout) != "2026-03-12" {
57			t.Fatalf("unexpected %+v", created)
58		}
59		if strings.Join(created.Tags, ",") != "home,errands" {
60			t.Fatalf("tags not normalized: %v", created.Tags)
61		}
62		if got := rec.Header().Get("Location"); got != "/tasks/t0001" {
63			t.Fatalf("location %q", got)
64		}
65		rec = do(t, h, "GET", "/tasks/t0001", "")
66		if rec.Code != 200 || decode[Task](t, rec).Title != "Buy milk" {
67			t.Fatalf("get: %d %s", rec.Code, rec.Body)
68		}
69	}
70	
71	func TestCreateValidation(t *testing.T) {
72		_, h := newTestServer(t)
73		for _, body := range []string{
74			`{"title":""}`,
75			`{"title":"x","due":"12/03/2026"}`,
76			`{"title":"x","tags":["a","b","c","d","e","f"]}`,
77			`not json`,
78		} {
79			if rec := do(t, h, "POST", "/tasks", body); rec.Code != http.StatusBadRequest {
80				t.Errorf("%s: got %d, want 400", body, rec.Code)
81			}
82		}
83	}
84	
85	func TestGetUnknown(t *testing.T) {
86		_, h := newTestServer(t)
87		if rec := do(t, h, "GET", "/tasks/t0099", ""); rec.Code != http.StatusNotFound {
88			t.Fatalf("got %d", rec.Code)
89		}
90	}
91	
92	func TestPatchMarksDone(t *testing.T) {
93		_, h := newTestServer(t)
94		do(t, h, "POST", "/tasks", `{"title":"Call the plumber"}`)
95		rec := do(t, h, "PATCH", "/tasks/t0001", `{"done":true}`)
96		if rec.Code != 200 || !decode[Task](t, rec).Done {
97			t.Fatalf("patch: %d %s", rec.Code, rec.Body)
98		}
99	}
100	
101	func TestFilterByTag(t *testing.T) {
102		_, h := newTestServer(t)
103		do(t, h, "POST", "/tasks", `{"title":"a","tags":["work"]}`)
104		do(t, h, "POST", "/tasks", `{"title":"b","tags":["home"]}`)
105		got := decode[[]Task](t, do(t, h, "GET", "/tasks?tag=Work", ""))
106		if len(got) != 1 || got[0].Title != "a" {
107			t.Fatalf("got %+v", got)
108		}
109	}
110	
111	func TestOverdue(t *testing.T) {
112		_, h := newTestServer(t)
113		do(t, h, "POST", "/tasks", `{"title":"late","due":"2026-03-01"}`)
114		do(t, h, "POST", "/tasks", `{"title":"later","due":"2026-04-01"}`)
115		do(t, h, "POST", "/tasks", `{"title":"late but done","due":"2026-03-02"}`)
116		do(t, h, "PATCH", "/tasks/t0003", `{"done":true,"due":"2026-03-02"}`)
117		got := decode[[]Task](t, do(t, h, "GET", "/tasks?overdue=true", ""))
118		if len(got) != 1 || got[0].Title != "late" {
119			t.Fatalf("got %+v", got)
120		}
121	}
122	
123	func TestDelete(t *testing.T) {
124		_, h := newTestServer(t)
125		do(t, h, "POST", "/tasks", `{"title":"x"}`)
126		if rec := do(t, h, "DELETE", "/tasks/t0001", ""); rec.Code != http.StatusNoContent {
127			t.Fatalf("got %d", rec.Code)
128		}
129		if rec := do(t, h, "GET", "/tasks/t0001", ""); rec.Code != http.StatusNotFound {
130			t.Fatalf("after delete got %d", rec.Code)
131		}
132	}
